<!-- Mobile Navigation Drawer & Scripts -->
<script>
document.addEventListener("DOMContentLoaded", function() {
  // Initialize Lucide Icons
  if (typeof lucide !== 'undefined' && lucide.createIcons) {
    lucide.createIcons();
  }

  // Mobile nav toggle matching PublicBottomNavMobile.tsx
  var mnavToggle = document.querySelector(".mnav__toggle");
  var mnavMenu = document.querySelector(".mnav__menu");
  var mnav = document.querySelector(".mnav");
  if (mnavToggle && mnavMenu) {
    mnavToggle.addEventListener("click", function(e) {
      e.stopPropagation();
      var isHidden = mnavMenu.style.display === "none";
      mnavMenu.style.display = isHidden ? "grid" : "none";
      mnavToggle.setAttribute("aria-expanded", isHidden ? "true" : "false");
    });

    // Close on click outside
    document.addEventListener("click", function(e) {
      if (mnav && !mnav.contains(e.target) && mnavMenu.style.display !== "none") {
        mnavMenu.style.display = "none";
        mnavToggle.setAttribute("aria-expanded", "false");
      }
    });

    // Close on Escape key
    document.addEventListener("keydown", function(e) {
      if (e.key === "Escape" && mnavMenu.style.display !== "none") {
        mnavMenu.style.display = "none";
        mnavToggle.setAttribute("aria-expanded", "false");
      }
    });
  }

  // Accordion triggers (FAQs etc)
  document.querySelectorAll("[data-radix-collection-item], button[data-state]").forEach(function(btn) {
    btn.addEventListener("click", function() {
      var state = btn.getAttribute("data-state");
      var nextState = state === "open" ? "closed" : "open";
      btn.setAttribute("data-state", nextState);
      var contentId = btn.getAttribute("aria-controls");
      if (contentId) {
        var content = document.getElementById(contentId);
        if (content) {
          content.setAttribute("data-state", nextState);
          if (nextState === "open") {
            content.removeAttribute("hidden");
          } else {
            content.setAttribute("hidden", "");
          }
        }
      }
    });
  });

  // Authentic Scroll Reveal IntersectionObserver (matching ikan2)
  var revealElements = document.querySelectorAll(".reveal, .about-reveal, [data-reveal]");
  if ("IntersectionObserver" in window) {
    var revealObserver = new IntersectionObserver(function(entries) {
      entries.forEach(function(entry) {
        if (entry.isIntersecting) {
          entry.target.classList.add("reveal-in", "is-in");
          revealObserver.unobserve(entry.target);
        }
      });
    }, { rootMargin: "0px 0px -4% 0px", threshold: 0.05 });

    revealElements.forEach(function(el) {
      if (!el.classList.contains("reveal-in") && !el.classList.contains("is-in")) {
        revealObserver.observe(el);
      }
    });

    // Safety fallback: reveal all elements after 1s so content is never hidden on mobile
    setTimeout(function() {
      revealElements.forEach(function(el) {
        el.classList.add("reveal-in", "is-in");
      });
    }, 1000);
  } else {
    revealElements.forEach(function(el) {
      el.classList.add("reveal-in", "is-in");
    });
  }

  // Universal Newsletter Subscription Handler
  document.querySelectorAll("form").forEach(function(nForm) {
    var emailInput = nForm.querySelector("#newsletter-email") || nForm.querySelector("input[name='email']");
    var submitBtn = nForm.querySelector("button[type='submit']");
    if (!emailInput || !submitBtn || nForm.id === "form-user-login" || nForm.id === "form-user-register" || nForm.id === "contact-form") {
      return;
    }

    nForm.addEventListener("submit", async function(e) {
      e.preventDefault();
      var emailVal = emailInput.value.trim();
      if (!emailVal || emailVal.indexOf("@") === -1) return;

      var origHtml = submitBtn.innerHTML;
      submitBtn.disabled = true;
      submitBtn.textContent = "Subscribing...";

      var fd = new FormData();
      fd.append("action", "ikan_newsletter_submit");
      fd.append("nonce", window.ikanAjax ? window.ikanAjax.nonce : "");
      fd.append("email", emailVal);

      try {
        var ajaxUrl = window.ikanAjax ? window.ikanAjax.ajax_url : "/wp-admin/admin-ajax.php";
        var res = await fetch(ajaxUrl, { method: "POST", body: fd });
        var data = await res.json();
        if (data && data.success) {
          nForm.innerHTML = '<div class="p-3 bg-emerald-50 text-emerald-800 rounded-xl text-xs font-semibold text-center">' + (data.data && data.data.message ? data.data.message : "Thank you! You are subscribed.") + '</div>';
        } else {
          alert(data && data.data && data.data.message ? data.data.message : "Subscription error. Please try again.");
          submitBtn.disabled = false;
          submitBtn.innerHTML = origHtml;
        }
      } catch (err) {
        alert("Network error. Please try again.");
        submitBtn.disabled = false;
        submitBtn.innerHTML = origHtml;
      }
    });
  });
});
</script>

<?php wp_footer(); ?>
</body>
</html>
